/* Documentation sidebar and search.
 *
 * - Highlights the current page in the table of contents.
 * - Searches search-index.json, which is generated by
 *   tools/build-docs-index.mjs and committed alongside the docs.
 *
 * No dependencies and no inline handlers. Results are built with
 * createElement/textContent rather than innerHTML, so nothing read from the
 * index can ever be parsed as markup.
 */
(() => {
  "use strict";

  const norm = (p) => p.replace(/index\.html$/, "").replace(/\/+$/, "");

  /* ---------- current page in the table of contents ---------- */
  const links = document.querySelectorAll(".docs-nav__list a");
  if (links.length) {
    const here = norm(location.pathname);
    links.forEach((a) => {
      if (norm(a.getAttribute("href")) === here) {
        a.classList.add("is-current");
        a.setAttribute("aria-current", "page");
      }
    });
  }

  /* ---------- search ---------- */
  const root = document.querySelector("[data-docs-search]");
  if (!root) return;

  const input = root.querySelector("#docs-search-input");
  const list = root.querySelector("#docs-search-results");
  const status = root.querySelector(".docs-search__status");
  const MAX_RESULTS = 8;

  let indexPromise = null;
  let entries = null;
  let results = [];
  let active = -1;

  const loadIndex = () => {
    if (!indexPromise) {
      indexPromise = fetch("/search-index.json", { credentials: "same-origin" })
        .then((r) => (r.ok ? r.json() : []))
        .catch(() => []);
    }
    return indexPromise;
  };

  const tokenize = (s) => s.toLowerCase().split(/[^a-z0-9]+/).filter((t) => t.length > 1);

  /* Every token has to appear somewhere; the score reflects where. */
  const score = (entry, tokens) => {
    const title = entry.title.toLowerCase();
    const section = (entry.section || "").toLowerCase();
    const text = entry.text.toLowerCase();
    let total = 0;
    for (const t of tokens) {
      if (title.includes(t)) total += 10;
      else if (section.includes(t)) total += 6;
      else if (text.includes(t)) total += 2;
      else return 0;
    }
    return total;
  };

  const snippet = (entry, tokens) => {
    const text = entry.text;
    const lower = text.toLowerCase();
    let at = -1;
    for (const t of tokens) {
      const i = lower.indexOf(t);
      if (i !== -1 && (at === -1 || i < at)) at = i;
    }
    if (at === -1) return text.slice(0, 120).trim();
    const start = Math.max(0, at - 40);
    return (start > 0 ? "…" : "") + text.slice(start, start + 120).trim() + "…";
  };

  const close = () => {
    list.hidden = true;
    list.textContent = "";
    input.setAttribute("aria-expanded", "false");
    input.removeAttribute("aria-activedescendant");
    results = [];
    active = -1;
  };

  const highlight = (n) => {
    [...list.children].forEach((li, i) => {
      const on = i === n;
      li.classList.toggle("is-active", on);
      li.setAttribute("aria-selected", String(on));
    });
    const el = list.children[n];
    if (el) el.scrollIntoView({ block: "nearest" });
    if (n >= 0) input.setAttribute("aria-activedescendant", "docs-search-option-" + n);
  };

  const render = (query, tokens) => {
    list.textContent = "";
    results = (entries || [])
      .map((entry) => ({ entry, s: score(entry, tokens) }))
      .filter((x) => x.s > 0)
      .sort((a, b) => b.s - a.s)
      .slice(0, MAX_RESULTS)
      .map((x) => x.entry);

    if (!results.length) {
      close();
      status.textContent = 'No matches for "' + query + '".';
      return;
    }

    results.forEach((entry, i) => {
      const li = document.createElement("li");
      li.className = "docs-search__result";
      li.id = "docs-search-option-" + i;
      li.setAttribute("role", "option");
      li.setAttribute("aria-selected", "false");

      const a = document.createElement("a");
      a.href = entry.url + (entry.anchor ? "#" + entry.anchor : "");

      const title = document.createElement("span");
      title.className = "docs-search__result-title";
      title.textContent = entry.section ? entry.title + " › " + entry.section : entry.title;

      const snip = document.createElement("span");
      snip.className = "docs-search__result-snippet";
      snip.textContent = snippet(entry, tokens);

      a.append(title, snip);
      li.append(a);
      li.addEventListener("mouseenter", () => { active = i; highlight(i); });
      list.append(li);
    });

    list.hidden = false;
    input.setAttribute("aria-expanded", "true");
    status.textContent = results.length + (results.length === 1 ? " result" : " results");
    active = -1;
  };

  let timer = null;
  const run = async () => {
    const query = input.value.trim();
    if (query.length < 2) { close(); status.textContent = ""; return; }
    const tokens = tokenize(query);
    if (!tokens.length) { close(); return; }
    if (!entries) entries = await loadIndex();
    render(query, tokens);
  };

  input.addEventListener("input", () => {
    clearTimeout(timer);
    timer = setTimeout(run, 120);
  });

  input.addEventListener("focus", () => { loadIndex(); });

  input.addEventListener("keydown", (e) => {
    if (e.key === "Escape") {
      input.value = "";
      close();
      status.textContent = "";
      return;
    }
    if (list.hidden || !results.length) return;
    if (e.key === "ArrowDown" || e.key === "ArrowUp") {
      e.preventDefault();
      active = e.key === "ArrowDown"
        ? (active + 1) % results.length
        : (active - 1 + results.length) % results.length;
      highlight(active);
    } else if (e.key === "Enter" && active >= 0) {
      e.preventDefault();
      list.children[active].querySelector("a").click();
    }
  });

  document.addEventListener("click", (e) => {
    if (!root.contains(e.target)) close();
  });
})();
